     1→/**
     2→ * FreeWire Phase 8-10 Tests
     3→ * RepairHistory + PatternAdvisor + ContractInferrer + AdaptiveLoop
     4→ *
     5→ * 총 50개 테스트
     6→ */
     7→
     8→'use strict';
     9→
    10→const { RepairHistory }    = require('../intent/repair-history');
    11→const { PatternAdvisor }   = require('../intent/pattern-advisor');
    12→const { ContractInferrer, mergeInferredContract } = require('../intent/contract-inferrer');
    13→const {
    14→  AdaptiveLoop,
    15→  createAdaptiveLoop,
    16→  resetGlobalHistory,
    17→  getGlobalHistory,
    18→  defaultNextId,
    19→} = require('../intent/adaptive-loop');
    20→
    21→// ─── 테스트 유틸 ─────────────────────────────────────────────
    22→
    23→let passed = 0, failed = 0;
    24→
    25→function test(name, fn) {
    26→  try {
    27→    fn();
    28→    console.log(`  ✓ ${name}`);
    29→    passed++;
    30→  } catch (e) {
    31→    console.error(`  ✗ ${name}`);
    32→    console.error(`    → ${e.message}`);
    33→    failed++;
    34→  }
    35→}
    36→
    37→function assert(condition, msg = 'assertion failed') {
    38→  if (!condition) throw new Error(msg);
    39→}
    40→
    41→function assertEqual(a, b, msg) {
    42→  if (a !== b) throw new Error(msg ?? `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
    43→}
    44→
    45→function assertIn(arr, val, msg) {
    46→  if (!arr.includes(val)) throw new Error(msg ?? `${JSON.stringify(val)} not in ${JSON.stringify(arr)}`);
    47→}
    48→
    49→// ─── 노드/와이어 팩토리 ──────────────────────────────────────
    50→
    51→function makeNode(id, subtype, props = {}, contract = null) {
    52→  const def = {
    53→    id, type: 'component', subtype,
    54→    label: `${subtype}[${id}]`,
    55→    inputs:  [{ name: 'in',  portType: 'data' }],
    56→    outputs: [{ name: 'out', portType: 'data' }],
    57→    props,
    58→    position: { x: 100, y: 100 },
    59→    ...(contract ? { contract } : {}),
    60→  };
    61→  return [id, def];
    62→}
    63→
    64→function makeNodes(...defs) {
    65→  const m = new Map();
    66→  for (const [id, def] of defs) m.set(id, def);
    67→  return m;
    68→}
    69→
    70→function makeWires(...entries) {
    71→  const m = new Map();
    72→  for (const [id, fn, tn, fp = 0, tp = 0] of entries) {
    73→    m.set(id, { id, fn, fp, tn, tp });
    74→  }
    75→  return m;
    76→}
    77→
    78→// ═══════════════════════════════════════════════════════════════
    79→// Phase 8: RepairHistory
    80→// ═══════════════════════════════════════════════════════════════
    81→
    82→console.log('\n[Phase 8] RepairHistory');
    83→
    84→test('기본 record 저장', () => {
    85→  const h = new RepairHistory();
    86→  h.record('s1',
    87→    { type: 'structural', fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    88→    { type: 'add_wire', description: '연결', confidence: 0.9 },
    89→    80, 60
    90→  );
    91→  assertEqual(h.stats().totalRecords, 1);
    92→});
    93→
    94→test('improved 플래그 계산', () => {
    95→  const h = new RepairHistory();
    96→  h.record('s1',
    97→    { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
    98→    { type: 'add_wire', description: '연결', confidence: 0.9 },
    99→    80, 60  // 60→80: improved
   100→  );
   101→  h.record('s1',
   102→    { fact: 'state.bound', repairHint: 'wire_state_to_display', nodeSubtype: 'state' },
   103→    { type: 'add_wire', description: '바인딩', confidence: 0.8 },
   104→    70, 80  // 80→70: not improved
   105→  );
   106→  const stats = h.stats();
   107→  assertEqual(stats.improvedCount, 1);
   108→  assertEqual(stats.successRate, 50);
   109→});
   110→
   111→test('patternCount 집계', () => {
   112→  const h = new RepairHistory();
   113→  for (let i = 0; i < 5; i++) {
   114→    h.record(`s${i}`,
   115→      { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
   116→      { type: 'add_wire', description: '연결', confidence: 0.9 },
   117→      80, 60
   118→    );
   119→  }
   120→  assertEqual(h.patternCount('button', 'ui.button.connected'), 5);
   121→});
   122→
   123→test('topViolations 정렬', () => {
   124→  const h = new RepairHistory();
   125→  // button 위반 3번
   126→  for (let i = 0; i < 3; i++) h.record(`s${i}`,
   127→    { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'button' },
   128→    null, 50, 50
   129→  );
   130→  // state 위반 5번
   131→  for (let i = 0; i < 5; i++) h.record(`s${i}`,
   132→    { fact: 'state.bound', repairHint: 'w', nodeSubtype: 'state' },
   133→    null, 50, 50
   134→  );
   135→  const top = h.topViolations(1);
   136→  assert(top[0].pattern.includes('state'), 'state가 1위여야');
   137→  assertEqual(top[0].count, 5);
   138→});
   139→
   140→test('patchEfficacy 계산', () => {
   141→  const h = new RepairHistory();
   142→  // 3번 적용, 2번 성공
   143→  h.record('s1', { fact: 'f', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
   144→    { type: 'add_wire', description: '연결', confidence: 0.9 }, 80, 60); // improved
   145→  h.record('s2', { fact: 'f', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
   146→    { type: 'add_wire', description: '연결', confidence: 0.9 }, 70, 60); // improved
   147→  h.record('s3', { fact: 'f', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
   148→    { type: 'add_wire', description: '연결', confidence: 0.9 }, 50, 60); // not improved
   149→  const e = h.patchEfficacy('add_wire', 'wire_handler_to_button');
   150→  assert(Math.abs(e - 2/3) < 0.01, `efficacy should be ~0.67, got ${e}`);
   151→});
   152→
   153→test('bestPatchFor 조회', () => {
   154→  const h = new RepairHistory();
   155→  h.record('s1', { fact: 'f', repairHint: 'add_handler_node', nodeSubtype: 'button' },
   156→    { type: 'add_node', description: '핸들러 추가', confidence: 0.85 }, 90, 60);
   157→  h.record('s2', { fact: 'f', repairHint: 'add_handler_node', nodeSubtype: 'button' },
   158→    { type: 'add_node', description: '핸들러 추가', confidence: 0.85 }, 85, 60);
   159→  const best = h.bestPatchFor('add_handler_node');
   160→  assert(best !== null, 'bestPatch found');
   161→  assertEqual(best.patchType, 'add_node');
   162→});
   163→
   164→test('sessionSummary 집계', () => {
   165→  const h = new RepairHistory();
   166→  h.record('mySession', { fact: 'f1', repairHint: 'r', nodeSubtype: 'button' },
   167→    { type: 'add_wire', description: 'test', confidence: 0.9 }, 80, 60);
   168→  h.record('mySession', { fact: 'f2', repairHint: 'r', nodeSubtype: 'state' },
   169→    { type: 'add_wire', description: 'test', confidence: 0.8 }, 90, 80);
   170→  const s = h.sessionSummary('mySession');
   171→  assertEqual(s.totalPatches, 2);
   172→  assertEqual(s.improved, 2);
   173→});
   174→
   175→test('maxRecords 제한', () => {
   176→  const h = new RepairHistory(5);
   177→  for (let i = 0; i < 10; i++) {
   178→    h.record(`s${i}`, { fact: 'f', repairHint: 'r', nodeSubtype: null },
   179→      null, 50, 50);
   180→  }
   181→  assert(h._records.length <= 5, 'maxRecords 초과하면 안 됨');
   182→});
   183→
   184→test('toJSON/fromJSON 직렬화', () => {
   185→  const h = new RepairHistory();
   186→  h.record('s1', { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
   187→    { type: 'add_wire', description: '연결', confidence: 0.9 }, 80, 60);
   188→  const json = h.toJSON();
   189→  const h2 = RepairHistory.fromJSON(json);
   190→  assertEqual(h2.stats().totalRecords, 1);
   191→  assertEqual(h2.patternCount('button', 'ui.button.connected'), 1);
   192→});
   193→
   194→// ═══════════════════════════════════════════════════════════════
   195→// Phase 8: PatternAdvisor
   196→// ═══════════════════════════════════════════════════════════════
   197→
   198→console.log('\n[Phase 8] PatternAdvisor');
   199→
   200→test('빈 이력에서 조언 없음', () => {
   201→  const h = new RepairHistory();
   202→  const advisor = new PatternAdvisor(h);
   203→  const nodes = [{ id: 'b1', subtype: 'button', props: {} }];
   204→  const advices = advisor.advise(nodes);
   205→  assertEqual(advices.length, 0, '이력 없으면 조언 없음');
   206→});
   207→
   208→test('버튼+핸들러 누락 패턴 경고', () => {
   209→  const h = new RepairHistory();
   210→  // 버튼:핸들러 누락 3번 기록
   211→  for (let i = 0; i < 3; i++) {
   212→    h.record(`s${i}`,
   213→      { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
   214→      null, 50, 50
   215→    );
   216→  }
   217→  const advisor = new PatternAdvisor(h);
   218→  // 버튼은 있고 핸들러는 없는 그래프
   219→  const nodes = [{ id: 'b1', subtype: 'button', props: {} }];
   220→  const advices = advisor.advise(nodes);
   221→  assert(advices.length > 0, '경고가 있어야 함');
   222→  assert(advices[0].occurrences >= 3, '발생 횟수 반영');
   223→});
   224→
   225→test('패치 신뢰도 보정 (충분한 이력)', () => {
   226→  const h = new RepairHistory();
   227→  // 5번 적용, 4번 성공 → efficacy = 0.8
   228→  for (let i = 0; i < 5; i++) {
   229→    h.record(`s${i}`,
   230→      { fact: 'ui.button.connected', repairHint: 'add_handler_node', nodeSubtype: 'button' },
   231→      { type: 'add_node', description: '핸들러 추가', confidence: 0.85 },
   232→      i < 4 ? 80 : 50, 60  // 4번 개선
   233→    );
   234→  }
   235→  const advisor = new PatternAdvisor(h);
   236→  const patch = { type: 'add_node', description: '핸들러 추가', confidence: 0.5 };
   237→  const [adjusted] = advisor.adjustConfidence([patch]);
   238→  // efficacy(0.8) * 0.6 + confidence(0.5) * 0.4 = 0.68
   239→  assert(adjusted.confidence > 0.5, '이력 기반 상향 보정');
   240→});
   241→
   242→test('패치 신뢰도 보정 (부족한 이력 - 유지)', () => {
   243→  const h = new RepairHistory();
   244→  // 2번만 기록 (3번 미만 → 보정 안 함)
   245→  for (let i = 0; i < 2; i++) {
   246→    h.record(`s${i}`,
   247→      { fact: 'f', repairHint: 'r', nodeSubtype: null },
   248→      { type: 'add_node', description: '테스트', confidence: 0.85 },
   249→      80, 60
   250→    );
   251→  }
   252→  const advisor = new PatternAdvisor(h);
   253→  const patch = { type: 'add_node', description: '테스트', confidence: 0.7 };
   254→  const [adjusted] = advisor.adjustConfidence([patch]);
   255→  assertEqual(adjusted.confidence, 0.7, '이력 부족 시 원래 confidence 유지');
   256→});
   257→
   258→test('suggestMissingNodes — 버튼 있으면 핸들러 제안', () => {
   259→  const h = new RepairHistory();
   260→  h.record('s1', { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'handler' },
   261→    null, 50, 50);
   262→  const advisor = new PatternAdvisor(h);
   263→  const nodes = [{ id: 'b1', subtype: 'button', props: {} }];
   264→  const suggestions = advisor.suggestMissingNodes(nodes);
   265→  assert(suggestions.some(s => s.subtype === 'handler'), '핸들러 제안');
   266→});
   267→
   268→test('isRepeatedMistake 판별', () => {
   269→  const h = new RepairHistory();
   270→  h.record('s1', { fact: 'state.bound', repairHint: 'w', nodeSubtype: 'state' }, null, 50, 50);
   271→  h.record('s2', { fact: 'state.bound', repairHint: 'w', nodeSubtype: 'state' }, null, 50, 50);
   272→  const advisor = new PatternAdvisor(h);
   273→  assert(advisor.isRepeatedMistake('state.bound', 'state'), '반복 실수 감지');
   274→  assert(!advisor.isRepeatedMistake('unknown.fact', 'button'), '처음 실수는 반복 아님');
   275→});
   276→
   277→test('learningReport 생성', () => {
   278→  const h = new RepairHistory();
   279→  h.record('s1', { fact: 'ui.button.connected', repairHint: 'w', nodeSubtype: 'button' },
   280→    { type: 'add_wire', description: 'test', confidence: 0.9 }, 80, 60);
   281→  const advisor = new PatternAdvisor(h);
   282→  const report = advisor.learningReport();
   283→  assert(report.includes('학습 리포트'), '리포트 헤더');
   284→  assert(report.includes('총 수정 이력'), '총 이력');
   285→});
   286→
   287→// ═══════════════════════════════════════════════════════════════
   288→// Phase 9: ContractInferrer
   289→// ═══════════════════════════════════════════════════════════════
   290→
   291→console.log('\n[Phase 9] ContractInferrer');
   292→
   293→test('버튼 노드 — 로그인 label → auth.initiated 추론', () => {
   294→  const inferrer = new ContractInferrer();
   295→  const node = { id: 'b1', subtype: 'button', props: { label: '로그인' }, contract: null };
   296→  const result = inferrer.infer(node);
   297→  assertIn(result.produces, 'auth.initiated', 'auth.initiated 추론');
   298→});
   299→
   300→test('버튼 노드 — 제출 label → form.submitted 추론', () => {
   301→  const inferrer = new ContractInferrer();
   302→  const node = { id: 'b1', subtype: 'button', props: { label: '제출하기' } };
   303→  const result = inferrer.infer(node);
   304→  assertIn(result.produces, 'form.submitted');
   305→});
   306→
   307→test('input 노드 — email type → form.email.filled 추론', () => {
   308→  const inferrer = new ContractInferrer();
   309→  const node = { id: 'i1', subtype: 'input', props: { type: 'email', placeholder: '이메일' } };
   310→  const result = inferrer.infer(node);
   311→  assertIn(result.produces, 'form.email.filled');
   312→});
   313→
   314→test('state 노드 — count name → counter.state.available 추론', () => {
   315→  const inferrer = new ContractInferrer();
   316→  const node = { id: 's1', subtype: 'state', props: { name: 'count', initial: 0 } };
   317→  const result = inferrer.infer(node);
   318→  assertIn(result.produces, 'counter.state.available');
   319→  assertIn(result.produces, 'state.available');
   320→});
   321→
   322→test('handler 노드 — requires action.triggered 추론', () => {
   323→  const inferrer = new ContractInferrer();
   324→  const node = { id: 'h1', subtype: 'handler', props: { name: 'handleLogin' } };
   325→  const result = inferrer.infer(node);
   326→  assertIn(result.requires, 'action.triggered');
   327→  assertIn(result.ensures, 'auth.handler.ready');
   328→});
   329→
   330→test('text 노드 — state.bound warns 추론', () => {
   331→  const inferrer = new ContractInferrer();
   332→  const node = { id: 't1', subtype: 'text', props: { content: '카운트:' } };
   333→  const result = inferrer.infer(node);
   334→  assertIn(result.warns, 'state.bound');
   335→});
   336→
   337→test('goal text 기반 facts 추론', () => {
   338→  const inferrer = new ContractInferrer();
   339→  const node = { id: 'b1', subtype: 'button', props: { label: '클릭' } };
   340→  const result = inferrer.infer(node, [], [], '로그인 폼 만들어줘');
   341→  assertIn(result.produces, 'auth.initiated');
   342→  assertIn(result.sources, 'goal_text');
   343→});
   344→
   345→test('구조 기반 추론 — 핸들러가 버튼 소스 → ui.button.connected 추론', () => {
   346→  const inferrer = new ContractInferrer();
   347→  const btnNode = { id: 'b1', subtype: 'button', props: {} };
   348→  const hdlNode = { id: 'h1', subtype: 'handler', props: {} };
   349→  const wires   = [{ fn: 'b1', tn: 'h1', fp: 0, tp: 0 }];
   350→  const result  = inferrer.infer(hdlNode, [btnNode, hdlNode], wires);
   351→  // handler가 button으로부터 wire 받음 → ui.button.connected
   352→  assertIn(result.produces, 'ui.button.connected');
   353→});
   354→
   355→test('inferAll — contract 없는 노드에만 적용', () => {
   356→  const inferrer = new ContractInferrer();
   357→  const nodes = makeNodes(
   358→    makeNode('b1', 'button', { label: '로그인' }),
   359→    ['n2', {
   360→      id: 'n2', type: 'component', subtype: 'input',
   361→      props: { type: 'email' },
   362→      contract: { requires: ['x'], ensures: [], produces: ['existing.fact'], warns: [] },
   363→    }]
   364→  );
   365→  const result = inferrer.inferAll(nodes, new Map());
   366→  assert(result.has('b1'), 'contract 없는 버튼 추론');
   367→  assert(!result.has('n2'), '이미 contract 있는 노드는 건드리지 않음');
   368→});
   369→
   370→test('mergeInferredContract — 기존 contract 보존', () => {
   371→  const node = {
   372→    id: 'b1', subtype: 'button', props: {},
   373→    contract: { requires: ['x'], ensures: [], produces: ['my.fact'], warns: [] },
   374→  };
   375→  const inferred = { requires: ['y'], ensures: [], produces: ['inferred.fact'], warns: [], sources: [] };
   376→  const merged = mergeInferredContract(node, inferred);
   377→  assertIn(merged.contract.produces, 'my.fact', '기존 fact 보존');
   378→  assert(!merged.contract.produces.includes('inferred.fact'), '추론 fact 덮어쓰지 않음');
   379→});
   380→
   381→test('mergeInferredContract — 빈 contract에 추론 주입', () => {
   382→  const node = {
   383→    id: 'b1', subtype: 'button', props: { label: '로그인' },
   384→    contract: { requires: [], ensures: [], produces: [], warns: [] },
   385→  };
   386→  const inferrer = new ContractInferrer();
   387→  const inferred = inferrer.infer(node);
   388→  const merged = mergeInferredContract(node, inferred);
   389→  assertIn(merged.contract.produces, 'auth.initiated', '추론 주입');
   390→  assert(merged.contract._inferred, '_inferred 마킹');
   391→});
   392→
   393→test('추론 confidence 계산', () => {
   394→  const inferrer = new ContractInferrer();
   395→  // subtype template + props 분석 + goal text → 높은 confidence
   396→  const node = { id: 'b1', subtype: 'button', props: { label: '로그인' } };
   397→  const result = inferrer.infer(node, [], [], '로그인 폼 만들어줘');
   398→  assert(result.confidence > 0.5, `confidence > 0.5, got ${result.confidence}`);
   399→  assert(result.sources.length > 1, '여러 소스에서 추론');
   400→});
   401→
   402→// ═══════════════════════════════════════════════════════════════
   403→// Phase 10: AdaptiveLoop
   404→// ═══════════════════════════════════════════════════════════════
   405→
   406→console.log('\n[Phase 10] AdaptiveLoop');
   407→
   408→// 테스트 전 전역 이력 초기화
   409→resetGlobalHistory();
   410→
   411→test('기본 실행 — 빈 그래프', () => {
   412→  resetGlobalHistory();
   413→  const loop = createAdaptiveLoop({ maxIterations: 2 });
   414→  const result = loop.run('로그인 폼', new Map(), new Map());
   415→  assert(result.finalScore >= 0, '점수 계산');
   416→  assert(Array.isArray(result.trace), 'trace 반환');
   417→  assert(typeof result.learningSummary === 'string', 'learningSummary');
   418→});
   419→
   420→test('Contract 자동 추론 카운트', () => {
   421→  resetGlobalHistory();
   422→  const nodes = makeNodes(
   423→    makeNode('b1', 'button', { label: '로그인' }),
   424→    makeNode('i1', 'input', { type: 'email' })
   425→  );
   426→  const loop = createAdaptiveLoop({ maxIterations: 1 });
   427→  const result = loop.run('로그인 폼 만들어줘', nodes, new Map());
   428→  assert(result.inferredContracts >= 0, 'inferredContracts 카운트');
   429→});
   430→
   431→test('사전 경고 생성 (이력 있을 때)', () => {
   432→  resetGlobalHistory();
   433→  const h = getGlobalHistory();
   434→  // 이력에 버튼 관련 위반 3번 기록
   435→  for (let i = 0; i < 3; i++) {
   436→    h.record(`pre${i}`,
   437→      { fact: 'ui.button.connected', repairHint: 'wire_handler_to_button', nodeSubtype: 'button' },
