/**
 * FreeWire - 그래프 스냅샷 / Undo-Redo 시스템
 *
 * GraphHistory: 그래프 JSON 상태를 스택에 쌓아
 * undo / redo / clear 기능을 제공합니다.
 */

'use strict';

const MAX_SIZE = 50;

class GraphHistory {
  /**
   * @param {number} [maxSize=50]  히스토리 최대 보관 수
   */
  constructor(maxSize = MAX_SIZE) {
    if (typeof maxSize !== 'number' || maxSize < 1) {
      throw new Error('maxSize는 1 이상의 정수여야 합니다');
    }
    this._maxSize   = maxSize;
    this._past      = [];   // 이전 상태 스택 (index 0 = 가장 오래됨)
    this._future    = [];   // 되돌리기 취소 스택 (index 0 = 가장 최근 undo)
  }

  // ─── 주요 메서드 ────────────────────────────────────────────

  /**
   * 현재 그래프 상태를 직렬화하여 저장합니다.
   * redo 스택은 새 push 시 비워집니다.
   *
   * @param {object|string} graphJson  Graph#toJSON() 결과 또는 JSON 문자열
   */
  push(graphJson) {
    const snapshot = this._serialize(graphJson);
    this._past.push(snapshot);
    // 최대 개수 초과 시 가장 오래된 항목 제거
    if (this._past.length > this._maxSize) {
      this._past.shift();
    }
    // 새 상태가 추가되면 redo 스택 초기화
    this._future = [];
  }

  /**
   * 가장 최근 상태를 꺼내 반환합니다 (없으면 null).
   * 꺼낸 상태는 redo 스택으로 이동합니다.
   *
   * @returns {object|null}  역직렬화된 그래프 JSON 또는 null
   */
  undo() {
    if (!this.canUndo) return null;
    const snapshot = this._past.pop();
    this._future.push(snapshot);
    return this._deserialize(snapshot);
  }

  /**
   * 가장 최근 undo 상태를 꺼내 반환합니다 (없으면 null).
   * 꺼낸 상태는 다시 past 스택으로 이동합니다.
   *
   * @returns {object|null}  역직렬화된 그래프 JSON 또는 null
   */
  redo() {
    if (!this.canRedo) return null;
    const snapshot = this._future.pop();
    this._past.push(snapshot);
    return this._deserialize(snapshot);
  }

  /**
   * 모든 히스토리(past + future)를 초기화합니다.
   */
  clear() {
    this._past    = [];
    this._future  = [];
  }

  // ─── Getter ──────────────────────────────────────────────────

  /** undo 가능 여부 */
  get canUndo() {
    return this._past.length > 0;
  }

  /** redo 가능 여부 */
  get canRedo() {
    return this._future.length > 0;
  }

  /**
   * 현재 저장된 past 스냅샷 수
   * (redo 스택은 포함하지 않음)
   */
  get size() {
    return this._past.length;
  }

  // ─── 직렬화 헬퍼 ─────────────────────────────────────────────

  _serialize(graphJson) {
    if (typeof graphJson === 'string') return graphJson;
    return JSON.stringify(graphJson);
  }

  _deserialize(snapshot) {
    if (typeof snapshot === 'object') return snapshot;
    return JSON.parse(snapshot);
  }
}

